 public sealed partial class R25NetBot {
  const BindingFlags ShieldFields=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
  static object ShieldField(object o,string name){return o==null?null:o.GetType().GetField(name,ShieldFields).GetValue(o);}
  static string ShieldText(object o,string name){var v=ShieldField(o,name);return v==null?null:v.ToString();}
  [Serializable] sealed class ShieldRecord {public string table,id,kind,owner,reserved;public Vector3 position;public bool removed,consumed,hasView,active,eligible,culled;public float distance;}
  [Serializable] sealed class ShieldRecords {public string role,phase,kind,target,aimed,held,objective,utc;public long epoch;public Vector3 point,hand,actor;public int count,localRecords,ruleRecords,sharedRecords;public ShieldRecord[] records;}
  Vector3 shieldGripPoint;string shieldGripTarget,shieldGripKind;int shieldDumpSerial;
  static Vector3 ShieldPosition(object row){var f=row.GetType().GetField("Position",ShieldFields);if(f==null)return Vector3.zero;var p=f.GetValue(row);return p is Float3?V((Float3)p):(Vector3)p;}
  void ShieldTable(List<ShieldRecord> rows,string table,object values,Vector3 point){var dictionary=values as IDictionary;if(dictionary==null)return;foreach(DictionaryEntry e in dictionary){object v=e.Value;Vector3 at=ShieldPosition(v);if(Vector3.Distance(at,point)>2.1f)continue;var t=v.GetType();rows.Add(new ShieldRecord{table=table,id=e.Key.ToString(),kind=ShieldText(v,"Kind"),position=at,distance=Vector3.Distance(at,point),owner=t.GetField("Owner",ShieldFields)==null?null:ShieldText(v,"Owner"),reserved=t.GetField("Reserved",ShieldFields)==null?null:ShieldText(v,"Reserved"),removed=t.GetField("Removed",ShieldFields)!=null&&(bool)ShieldField(v,"Removed"),consumed=t.GetField("Consumed",ShieldFields)!=null&&(bool)ShieldField(v,"Consumed")});}}
  void ShieldGripDump(string phase){var local=root.Consumables;object state=ShieldField(local,"state"),rules=ShieldField(state,"rules");var rows=new List<ShieldRecord>();
   ShieldTable(rows,"rules.items",ShieldField(rules,"items"),shieldGripPoint);ShieldTable(rows,"state.sources",ShieldField(state,"sources"),shieldGripPoint);ShieldTable(rows,"lobby.foods",ShieldField(root.LanSession.Lobby,"foods"),shieldGripPoint);
   var views=(IDictionary)ShieldField(local,"items");foreach(DictionaryEntry e in views){object item=e.Value;var go=ShieldField(item,"View") as GameObject;var info=local.InspectItem(e.Key.ToString());Vector3 p=go!=null?go.transform.position:info!=null?V(info.Position):(Vector3)ShieldField(item,"InitialPosition");if(Vector3.Distance(p,shieldGripPoint)>2.1f&&e.Key.ToString()!=shieldGripTarget)continue;rows.Add(new ShieldRecord{table="consumables.items",id=e.Key.ToString(),kind=ShieldText(item,"Kind"),position=p,distance=Vector3.Distance(p,shieldGripPoint),hasView=go!=null,active=go!=null&&go.activeInHierarchy,eligible=(bool)ShieldField(item,"WorldVisible"),culled=(bool)ShieldField(item,"Culled"),owner=info==null?null:info.Owner,removed=info==null||info.Removed,reserved=info==null?null:info.ReservedBy});}
   foreach(var item in local.OwnedItems)rows.Add(new ShieldRecord{table="state.owned",id=item.Id,kind=item.Kind,owner="player",position=Vector3.zero,distance=-1});
   var claims=(IDictionary)ShieldField(root.LanSession,"pendingClaims");foreach(DictionaryEntry e in claims){object claim=e.Value;if(ShieldText(claim,"Kind")!="food")continue;rows.Add(new ShieldRecord{table="session.pendingClaims",id=ShieldText(claim,"Local"),kind=ShieldText(claim,"Value"),owner=ShieldText(claim,"Canonical"),distance=-1});}
   string aimed;Vector3 position;float distance;local.TryReadAimedWorldItem(2,out aimed,out position,out distance);
   var dump=new ShieldRecords{utc=DateTime.UtcNow.ToString("O"),role=mode,phase=phase,kind=shieldGripKind,target=shieldGripTarget,point=shieldGripPoint,hand=root.Rig.Right.position,actor=root.Rig.transform.position,epoch=root.LanSession.Lobby.Epoch,held=local.HeldId,aimed=aimed,objective=root.Pickup4Objective,count=Pickup4Count(shieldGripKind),localRecords=views.Count,ruleRecords=((IDictionary)ShieldField(rules,"items")).Count,sharedRecords=root.LanSession.Lobby.SharedFoods.Length,records=rows.ToArray()};
   File.WriteAllText(Path.Combine(captureFolder,mode+"-grip-"+(shieldDumpSerial++)+"-"+phase+".json"),JsonUtility.ToJson(dump,true));Write("shields-grip-records",phase+" kind="+shieldGripKind+" count="+dump.count+" target="+shieldGripTarget+" aimed="+aimed+" records="+rows.Count+" point="+shieldGripPoint.ToString("F3"));
  }
  bool ShieldChooseFood(string kind){float best=Single.MaxValue;bool found=false;foreach(var row in root.LanSession.Lobby.SharedFoods){if(row.Kind!=kind||row.Owner!=""||row.Consumed||!row.Id.StartsWith("r24-cache/food/",StringComparison.Ordinal))continue;Vector3 p=V(row.Position),actor=root.Rig.transform.position;if(Mathf.Abs(p.y-actor.y)>2.5f||Physics.Linecast(actor+Vector3.up*1.4f,p+Vector3.up*.2f,1<<0,QueryTriggerInteraction.Ignore))continue;float d=(p-actor).sqrMagnitude;if(d>=best)continue;best=d;shieldGripPoint=p;shieldGripTarget=row.Id;found=true;}return found;}
  readonly HashSet<string> shieldWitnessed=new HashSet<string>(StringComparer.Ordinal);float shieldWitnessAt;
  void ShieldWitness(){if(Time.realtimeSinceStartup<shieldWitnessAt)return;shieldWitnessAt=Time.realtimeSinceStartup+.15f;string other=mode=="host"?"join":"host";foreach(string file in Directory.GetFiles(captureFolder,other+"-grip-*.json")){if(!shieldWitnessed.Add(file))continue;var request=JsonUtility.FromJson<ShieldRecords>(File.ReadAllText(file));if(request.phase.StartsWith("peer-",StringComparison.Ordinal))continue;string priorTarget=shieldGripTarget,priorKind=shieldGripKind;Vector3 priorPoint=shieldGripPoint;shieldGripTarget=request.target;shieldGripKind=request.kind;shieldGripPoint=request.point;ShieldGripDump("peer-"+other+"-"+request.phase);shieldGripTarget=priorTarget;shieldGripKind=priorKind;shieldGripPoint=priorPoint;}}
  void ShieldGripPhoto(int index){var cam=root.Rig.Head;Vector3 prior=cam.transform.position;Quaternion rotation=cam.transform.rotation;cam.transform.position=shieldGripPoint+new Vector3(.65f,.55f,-.65f);cam.transform.rotation=Quaternion.LookRotation(shieldGripPoint+Vector3.up*.08f-cam.transform.position);Capture(index);cam.transform.SetPositionAndRotation(prior,rotation);}
  [Serializable] sealed class ShieldReset {public string id,kind;public Vector3 point;}
  void ShieldResetRequests(){foreach(string file in Directory.GetFiles(captureFolder,"shields-retire-*.json")){var request=JsonUtility.FromJson<ShieldReset>(File.ReadAllText(file));string priorTarget=shieldGripTarget,priorKind=shieldGripKind;Vector3 priorPoint=shieldGripPoint;shieldGripTarget=request.id;shieldGripKind=request.kind;shieldGripPoint=request.point;
   bool retired=root.Consumables.RetireUnownedWorldItem(request.id);ShieldGripDump("retired-local-"+Path.GetFileNameWithoutExtension(file));bool spawned=retired&&root.Consumables.Spawn(request.id+"/replacement",request.kind,request.point,false);Write("shields-reset",Path.GetFileName(file)+" retired="+retired+" replacement="+spawned);File.Move(file,file+".done");shieldGripTarget=priorTarget;shieldGripKind=priorKind;shieldGripPoint=priorPoint;}}
  IEnumerator ShieldsGripRun(){while(root==null||log==null||root.LanSession.Lobby==null){if(closed)yield break;yield return null;}enabled=false;requestedMap=true;
   float started=Time.realtimeSinceStartup,entered=-1,liveAt=-1,stepAt=-1,nextNote=0,nextCache=0;bool opened=false,requested=false,fixtures=false,selected=false,mapReset=false;int kindIndex=0,stage=0,firstCount=0,before=0;var pass=new List<string>();var failures=new List<string>();string preset=Arg("-ashfallNetBotShieldsPreset");if(preset.Length==0)preset="free_for_all";
   while(!closed&&Time.realtimeSinceStartup-started<250){if(probe!=null)probe.Frame();float now=Time.realtimeSinceStartup,dt=Mathf.Clamp(Time.unscaledDeltaTime,0,.1f);var lobby=root.LanSession.Lobby;if(lobby==null)break;bool host=lobby.State==R24LanLobbyState.Hosting;
    if(host&&!opened&&lobby.MemberCount>=2&&now-started>3)opened=root.LanSession.ShieldsOpenWarmup(Arg("-ashfallNetBotMap"));
    bool active=root.Ready&&!root.Lobby.Visible&&!root.LanSession.MapEntryBlocked&&lobby.SelectedMap!=null&&lobby.SelectedMap.Active&&!lobby.SelectedMap.Home;if(!active){yield return null;continue;}
    if(entered<0)entered=now;if(host&&!requested&&now-entered>12){requested=true;root.LanSession.RouteRoundRequest(R24PlayableMatchRules.ForPreset(preset,root.Map.MapId).With("zone_enabled",false).With("damage",0));Write("shields-grip-start",preset);}
    bool live=lobby.SelectedMap.Rules!=null&&root.Pickup4Live;if(live&&liveAt<0){liveAt=now;Write("shields-grip-live",preset);}
    Vector3 actor=root.Rig.transform.position,head=actor+Vector3.up*1.7f,left=head+root.Rig.transform.rotation*new Vector3(-.3f,-.4f,.3f),right=head+root.Rig.transform.rotation*new Vector3(.3f,-.4f,.3f);Vector2 move=Vector2.zero;Quaternion aim=root.Rig.transform.rotation;float grip=0;
    if(live&&now-liveAt>4){root.Gameplay.HolsterCurrent();ShieldWitness();if(host&&!mapReset&&Arg("-ashfallNetBotShieldsMapReset")=="true"&&now-liveAt>8){mapReset=true;root.WorldLoot.ResetMapLoot();Write("shields-map-reset","production ResetMapLoot after START MATCH");}
     if(host&&now>=nextCache){nextCache=now+.5f;foreach(var member in lobby.Members){R24LanPoseSnapshot pose;if(lobby.TryReadPresence(member.Actor,out pose))root.WorldLoot.ShieldsActivate(V(pose.Pose.Root.Position));}ShieldResetRequests();}
     if(host&&!fixtures){fixtures=true;foreach(var member in lobby.Members){R24LanPoseSnapshot pose;if(!lobby.TryReadPresence(member.Actor,out pose))continue;for(int i=0;i<3;i++)root.Supplies.Spawn("shields-backpack/"+member.Actor+"/"+i,"backpack",V(pose.Pose.Root.Position)+new Vector3(.6f,.9f,.4f+i*.3f),1);}}
     if(root.InventoryCapacity<6){Vector3 p;string id;if(Pickup4Target("backpack",out p,out id)){right=p-Vector3.forward*.12f;aim=Quaternion.LookRotation(p-right)*Quaternion.Inverse(R23TrackedGripPose.LocalRotation);grip=(now-liveAt)%1<.7f?.9f:0;}}
     else if(kindIndex<2&&now-liveAt>14){shieldGripKind=kindIndex==0?"soda":"shaker";
      if(!selected){root.Consumables.Stow();selected=ShieldChooseFood(shieldGripKind);stepAt=now;if(selected)Write("shields-grip-target",shieldGripKind+" "+shieldGripTarget+" at="+shieldGripPoint.ToString("F3"));}
      if(selected){Vector3 delta=Vector3.ProjectOnPlane(shieldGripPoint-actor,Vector3.up);
       if(stage==0&&delta.magnitude>1.0f){var dir=root.Rig.transform.InverseTransformDirection(delta);move=Vector2.ClampMagnitude(new Vector2(dir.x,dir.z)*.35f,.7f);if((now-liveAt)%10<.25f)move=Vector2.zero;if(now-stepAt>50){failures.Add(shieldGripKind+":approach-timeout");selected=false;stage=0;kindIndex++;}}
       else{right=shieldGripPoint-delta.normalized*.12f;aim=Quaternion.LookRotation(shieldGripPoint-right)*Quaternion.Inverse(R23TrackedGripPose.LocalRotation);
        if(stage==0){stage=Arg("-ashfallNetBotShieldsRebuild")=="true"?10:1;stepAt=now;before=Pickup4Count(shieldGripKind);ShieldGripDump(stage==10?"before-reset":"before-first");if(stage==1)ShieldGripPhoto(740+kindIndex);if(stage==10)File.WriteAllText(Path.Combine(captureFolder,"shields-retire-"+mode+"-"+shieldGripKind+".json"),JsonUtility.ToJson(new ShieldReset{id=shieldGripTarget,kind=shieldGripKind,point=shieldGripPoint}));}
        float t=now-stepAt;
        if(stage==1){grip=t>1&&t<4?.9f:0;if(t>4.5f){firstCount=Pickup4Count(shieldGripKind);ShieldGripDump("after-first");if(firstCount!=before+1)failures.Add(shieldGripKind+":first-delta="+(firstCount-before));else pass.Add(shieldGripKind+":first-one");root.Consumables.Stow();stage=2;stepAt=now;}}
        else if(stage==10){if(t>2.5f){stage=1;stepAt=now;before=Pickup4Count(shieldGripKind);ShieldGripDump("before-first");ShieldGripPhoto(740+kindIndex);}}
        else if(stage==2){if(t>.8f){ShieldGripDump("before-second");stage=3;stepAt=now;}}
        else if(stage==3){grip=t>.5f&&t<3?.9f:0;if(t>3.5f){int after=Pickup4Count(shieldGripKind);ShieldGripDump("after-second");Write("shields-grip-result",shieldGripKind+" before="+before+" first="+firstCount+" second="+after+" extra="+(after-firstCount));if(after!=firstCount)failures.Add(shieldGripKind+":second-extra="+(after-firstCount));else pass.Add(shieldGripKind+":second-zero");root.Consumables.Stow();stage=0;kindIndex++;selected=false;}}
       }
      }else if(now-liveAt>150){failures.Add(shieldGripKind+":no-target");kindIndex++;}
     }
    }
    root.Rig.NetBotSample(move,1.7f,left,right,aim,grip,0,dt);
    if(now>=nextNote){nextNote=now+5;Write("shields-grip-status","cap="+root.InventoryCapacity+" kind="+shieldGripKind+" stage="+stage+" live="+live+" actor="+actor.ToString("F2")+" "+root.Pickup4Objective);}
    if(kindIndex==2&&now-liveAt>(host?150:140))break;yield return null;
   }
   if(kindIndex!=2)failures.Add("incomplete");bool ok=failures.Count==0;Write("shields-grip-summary","passed="+ok,pass.ToArray(),failures.ToArray());closed=true;Passed=ok;Finished=true;root.LanSession.Leave();if(probe!=null){probe.Dispose();probe=null;}log.Dispose();log=null;if(!Application.isEditor)Application.Quit(ok?0:2);
  }
 }
